import{g as a,ae as t,r,B as i}from"./chunks/framework.CZ-ntRvv.js";const f=JSON.parse('{"title":"v1 Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"docs/changelog/v1.md","filePath":"docs/changelog/v1.md","lastUpdated":1791747207000}'),o={name:"docs/changelog/v1.md"};function n(l,e,s,h,p,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="v1-changelog" tabindex="-1">v1 Changelog <a class="header-anchor" href="#v1-changelog" aria-label="Permalink to “v1 Changelog”">​</a></h1><p>Every frappe-ui 1.x release, newest first. Each entry names its kind in parentheses (fix, additive or deprecation) and links to its pull request. To upgrade from v0, see <a href="/docs/changelog/v0-to-v1">Changes from v0 to v1</a> and the <a href="/docs/migration">migration guide</a>.</p><h2 id="_1-0-2" tabindex="-1">1.0.2 <a class="header-anchor" href="#_1-0-2" aria-label="Permalink to “1.0.2”">​</a></h2><h3 id="patch-changes" tabindex="-1">Patch Changes <a class="header-anchor" href="#patch-changes" aria-label="Permalink to “Patch Changes”">​</a></h3><ul><li>Editor: the suggestion menus (@mention, /, #, 😃 can now be clicked inside a Dialog without closing it (fix). <a href="https://github.com/frappe/frappe-ui/pull/1288" target="_blank" rel="noreferrer">#1288</a></li><li>Editor: @mention results now list an exact name match first, then names that start with the typed text, then names with a word that starts with it (fix). <a href="https://github.com/frappe/frappe-ui/pull/1288" target="_blank" rel="noreferrer">#1288</a></li><li>MobileShell: in an installed iOS 26 app, the tab bar now reaches the bottom edge and clears the home indicator; <code>frappe-ui/style.css</code> now gives every installed app with a translucent status bar a page at least as tall as the screen, which is what restores the full-screen viewport (fix). <a href="https://github.com/frappe/frappe-ui/pull/1289" target="_blank" rel="noreferrer">#1289</a></li><li>Combobox, MultiSelect: search results now list exact matches first, then labels that start with the typed text, then labels with a word that starts with it (fix). <a href="https://github.com/frappe/frappe-ui/pull/1290" target="_blank" rel="noreferrer">#1290</a></li><li>Vite plugin: an app linked into a bench&#39;s <code>apps/</code> from another folder now builds and runs in dev; tools such as Pilot set <code>FRAPPE_BENCH_PATH</code> to the bench (fix). <a href="https://github.com/frappe/frappe-ui/pull/1283" target="_blank" rel="noreferrer">#1283</a></li></ul><h2 id="_1-0-1" tabindex="-1">1.0.1 <a class="header-anchor" href="#_1-0-1" aria-label="Permalink to “1.0.1”">​</a></h2><h3 id="patch-changes-1" tabindex="-1">Patch Changes <a class="header-anchor" href="#patch-changes-1" aria-label="Permalink to “Patch Changes”">​</a></h3><ul><li>Charts: a category axis label that is shortened in the middle now keeps its ending, and no longer gets a second ellipsis at the end (fix). <a href="https://github.com/frappe/frappe-ui/pull/1279" target="_blank" rel="noreferrer">#1279</a></li><li>Checkbox: a checked or indeterminate checkbox now lightens on hover and press, and checkboxes no longer show a shadow on hover (fix). <a href="https://github.com/frappe/frappe-ui/pull/1186" target="_blank" rel="noreferrer">#1186</a></li><li>Editor: images and videos without a size get one only after the person&#39;s own edit, not when a document opens or a collaborator edits it, and one Ctrl+Z now undoes the person&#39;s edit (fix). <a href="https://github.com/frappe/frappe-ui/pull/1266" target="_blank" rel="noreferrer">#1266</a></li><li>PageHeaderMobile: the <code>#prefix</code> and <code>#suffix</code> slots now follow the text direction, so in right-to-left pages the back button sits on the right (fix). <a href="https://github.com/frappe/frappe-ui/pull/1230" target="_blank" rel="noreferrer">#1230</a></li><li>Progress: a bar without a <code>label</code> now has the accessible name &quot;Progress&quot; instead of its percentage, so screen readers do not read the value twice (fix). <a href="https://github.com/frappe/frappe-ui/pull/1113" target="_blank" rel="noreferrer">#1113</a></li><li>SidebarRailItem: a <code>subtle</code> item paints no fill behind an image, so a rounded logo shows no gray rim at its corners (fix). <a href="https://github.com/frappe/frappe-ui/pull/1272" target="_blank" rel="noreferrer">#1272</a></li><li>Editor: dragging a link or selected text out of a read-only editor now carries the browser&#39;s URL or text, as it does from plain HTML (fix). <a href="https://github.com/frappe/frappe-ui/pull/1104" target="_blank" rel="noreferrer">#1104</a></li><li>Realtime: updates keep arriving after a reconnect and on a new socket (fix). <a href="https://github.com/frappe/frappe-ui/pull/1105" target="_blank" rel="noreferrer">#1105</a></li><li>Editor: the mention, emoji, tag and slash-command menus stay next to the caret when the page or the editor&#39;s scroll container scrolls or the window resizes, and never show a position meant for an older list (fix). <a href="https://github.com/frappe/frappe-ui/pull/1161" target="_blank" rel="noreferrer">#1161</a></li></ul>',8)])])}const g=a(o,[["render",n]]);export{f as __pageData,g as default};
